SELECT *, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) cost_share, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) cost_share_2, LAST_VALUE(carrier) IGNORE NULLS OVER w_part last_known_carrier, NTILE(10) OVER (PARTITION BY carrier, order_id ORDER BY cost DESC, id) cost_bucket, ROUND(cost / SUM(cost) OVER (PARTITION BY order_id), 4) cost_share_3 FROM shipments WINDOW w_part AS (PARTITION BY carrier ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
